<script setup lang="ts">
import {nextTick,ref} from 'vue';import type{UvTabItem}from './tabs.types'
interface Props{modelValue?:string;tabs:UvTabItem[];ariaLabel?:string};const props=withDefaults(defineProps<Props>(),{modelValue:'',ariaLabel:'Tabs'});const emit=defineEmits<{'update:modelValue':[value:string];change:[value:string]}>();const buttons=ref<HTMLButtonElement[]>([])
function select(id:string){const tab=props.tabs.find(t=>t.id===id);if(!tab||tab.disabled)return;emit('update:modelValue',id);emit('change',id)}
async function onKey(event:KeyboardEvent,index:number){const enabled=props.tabs.map((t,i)=>({...t,index:i})).filter(t=>!t.disabled);if(!enabled.length)return;const current=enabled.findIndex(t=>t.index===index);let next=current>=0?current:0;if(event.key==='ArrowRight')next=(next+1)%enabled.length;else if(event.key==='ArrowLeft')next=(next-1+enabled.length)%enabled.length;else if(event.key==='Home')next=0;else if(event.key==='End')next=enabled.length-1;else return;const target=enabled[next];if(!target)return;event.preventDefault();select(target.id);await nextTick();buttons.value[target.index]?.focus()}
</script>
<template><div class="uv-tabs"><div class="uv-tabs__list" role="tablist" :aria-label="ariaLabel"><button v-for="(tab,index) in tabs" :id="`tab-${tab.id}`" :key="tab.id" ref="buttons" class="uv-tabs__tab" :class="{'uv-tabs__tab--active':modelValue===tab.id}" type="button" role="tab" :aria-selected="modelValue===tab.id" :aria-controls="`panel-${tab.id}`" :tabindex="modelValue===tab.id?0:-1" :disabled="tab.disabled" @click="select(tab.id)" @keydown="onKey($event,index)">{{tab.label}}</button></div><div class="uv-tabs__panel" role="tabpanel" :id="`panel-${modelValue}`" :aria-labelledby="`tab-${modelValue}`"><slot :active="modelValue"/></div></div></template>
<style>.uv-tabs{font-family:var(--uv-font-sans,system-ui,sans-serif);color:var(--uv-color-text,#0f172a)}.uv-tabs__list{display:flex;gap:.25rem;border-bottom:1px solid var(--uv-color-border,#dbe3ef);overflow:auto}.uv-tabs__tab{position:relative;border:0;background:transparent;color:var(--uv-color-text-muted,#64748b);padding:.75rem 1rem;font-weight:700;white-space:nowrap}.uv-tabs__tab::after{content:'';position:absolute;left:.55rem;right:.55rem;bottom:-1px;height:2px;background:transparent}.uv-tabs__tab--active{color:var(--uv-color-primary,#2563eb)}.uv-tabs__tab--active::after{background:currentColor}.uv-tabs__tab:focus-visible{outline:0;box-shadow:inset var(--uv-focus-ring)}.uv-tabs__panel{padding:1rem 0}</style>
